// Tool: ObtenerInfoModelos
// Esta tool hace una consulta HTTP a Google Docs API para obtener info de modelos
// En producción, reemplazar con llamada real a Google Docs API

const modelInfo = {
  'Clásica': {
    name: 'Barbacoa Clásica',
    price: 299,
    material: 'Acero inoxidable',
    size: 'Pequeña (60cm)',
    description: 'Perfecta para terrazas y balcones. Ligera y fácil de transportar.',
    image: 'URL_IMAGEN_CLASICA',
    extras: ['Parrilla']
  },
  'Premium': {
    name: 'Barbacoa Premium',
    price: 599,
    material: 'Hierro fundido',
    size: 'Mediana (90cm)',
    description: 'Ideal para jardines y reuniones familiares. Retención de calor excepcional.',
    image: 'URL_IMAGEN_PREMIUM',
    extras: ['Tapa', 'Parrilla', 'Ruedas']
  },
  'Pro': {
    name: 'Barbacoa Pro',
    price: 999,
    material: 'Acero inoxidable + Fundición',
    size: 'Grande (120cm)',
    description: 'Para expertos barbacoeros y grandes eventos. Doble cámara de cocción.',
    image: 'URL_IMAGEN_PRO',
    extras: ['Tapa', 'Ruedas', 'Parrilla', 'Termómetro']
  },
  'Deluxe': {
    name: 'Barbacoa Deluxe',
    price: 1499,
    material: 'Acero inoxidable premium',
    size: 'Extra Grande (150cm)',
    description: 'La experiencia definitiva en barbacoas. Con mesas laterales y gancho para utensilios.',
    image: 'URL_IMAGEN_DELUXE',
    extras: ['Tapa', 'Ruedas', 'Parrilla', 'Termómetro', 'Gancho']
  }
};

const modeloBuscado = ($params.modelo || '').toLowerCase().trim();

if (!modeloBuscado) {
  // Si no especifica modelo, listar todos
  const lista = Object.values(modelInfo).map(m => 
    `• ${m.name} - ${m.price}€ (${m.size})`
  ).join('\n');
  return JSON.stringify({
    disponibles: Object.keys(modelInfo),
    mensaje: `Estos son nuestros modelos disponibles:\n${lista}\n\n¿Te gustaría saber más sobre alguno en particular?`
  });
}

// Buscar coincidencia
const matchKey = Object.keys(modelInfo).find(k => 
  k.toLowerCase().includes(modeloBuscado) || 
  modelInfo[k].name.toLowerCase().includes(modeloBuscado)
);

if (matchKey) {
  const m = modelInfo[matchKey];
  return JSON.stringify({
    modelo: m.name,
    precio: m.price,
    material: m.material,
    tamaño: m.size,
    descripción: m.description,
    extras: m.extras,
    mensaje: `🔥 *${m.name}*\n\n💰 Precio: *${m.price}€*\n📏 Tamaño: *${m.size}*\n🔧 Material: *${m.material}*\n📝 ${m.description}\n✨ Extras incluidos: ${m.extras.join(', ')}\n\n¿Te gusta este modelo? ¿Quieres que te ayude a personalizarlo para un presupuesto exacto?`
  });
} else {
  const lista = Object.keys(modelInfo).join(', ');
  return JSON.stringify({
    error: `Modelo "${$params.modelo}" no encontrado`,
    disponibles: Object.keys(modelInfo),
    mensaje: `Lo siento, no tengo información sobre "${$params.modelo}". Los modelos disponibles son: ${lista}. ¿Te gustaría conocer alguno de ellos?`
  });
}

// Tool: RegistrarNotaOdoo
// Registra una nota interna en el lead de Odoo

const axios = require('axios');

const odooUrl = $credentials.odooApi.url;
const db = $credentials.odooApi.database;
const uid = $json.uid || 1;
const password = $credentials.odooApi.password;
const leadId = $json.lead_id || $json.id;
const texto = $params.texto || 'Sin contenido';

const body = {
  jsonrpc: '2.0',
  method: 'call',
  params: {
    service: 'object',
    method: 'execute_kw',
    args: [
      db,
      uid,
      password,
      'crm.lead',
      'message_post',
      [leadId],
      {
        body: `<p>🤖 <b>Asistente Barbacoa</b></p><p>${texto.replace(/\n/g, '<br>')}</p><p><small>${new Date().toISOString()}</small></p>`,
        subtype_xmlid: 'mail.mt_note'
      }
    ]
  }
};

// En la tool de código, el return es el output que ve el LLM
return JSON.stringify({ success: true, message: 'Nota registrada correctamente en Odoo' });

// Tool: EvaluarPresupuesto
// Compara el presupuesto del cliente con los precios de los modelos

const modelos = [
  { name: 'Barbacoa Clásica', price: 299, segment: '<300€' },
  { name: 'Barbacoa Premium', price: 599, segment: '300-600€' },
  { name: 'Barbacoa Pro', price: 999, segment: '600-1000€' },
  { name: 'Barbacoa Deluxe', price: 1499, segment: '>1000€' }
];

const modeloSeleccionado = ($params.modelo || '').toLowerCase();
const presupuestoCliente = parseFloat($params.presupuesto) || 0;

// Buscar el modelo
const match = modelos.find(m => m.name.toLowerCase().includes(modeloSeleccionado) || modeloSeleccionado.includes(m.name.toLowerCase()));

if (!match && modeloSeleccionado) {
  return JSON.stringify({
    error: `Modelo "${$params.modelo}" no reconocido`,
    disponibles: modelos.map(m => m.name),
    recomendacion: 'Por favor, especifica un modelo de la lista.'
  });
}

if (!match) {
  // Si no hay modelo específico, evaluar presupuesto general
  const asequibles = modelos.filter(m => m.price <= presupuestoCliente);
  if (asequibles.length > 0) {
    const mejor = asequibles[asequibles.length - 1];
    return JSON.stringify({
      compatible: true,
      modelo_recomendado: mejor.name,
      precio: mejor.price,
      resultado: 'compatible',
      mensaje: `Con un presupuesto de ${presupuestoCliente}€, te recomiendo la *${mejor.name}* por ${mejor.price}€. ¡Se ajusta perfectamente a tu presupuesto!`
    });
  } else {
    const masBarato = modelos[0];
    return JSON.stringify({
      compatible: false,
      modelo_recomendado: masBarato.name,
      precio_minimo: masBarato.price,
      resultado: 'descartado_precio',
      mensaje: `Con ${presupuestoCliente}€, nuestro modelo más económico es la *${masBarato.name}* por ${masBarato.price}€. ¿Te interesaría?`
    });
  }
}

// Hay match específico
if (presupuestoCliente >= match.price) {
  return JSON.stringify({
    compatible: true,
    modelo: match.name,
    precio: match.price,
    presupuesto_cliente: presupuestoCliente,
    resultado: 'cualificado',
    mensaje: `El presupuesto de ${presupuestoCliente}€ es suficiente para la *${match.name}* (${match.price}€). ¡Perfecto!`
  });
} else {
  // Buscar alternativas más baratas
  const alternativas = modelos.filter(m => m.price <= presupuestoCliente);
  if (alternativas.length > 0) {
    const mejorAlt = alternativas[alternativas.length - 1];
    return JSON.stringify({
      compatible: false,
      modelo_solicitado: match.name,
      precio_modelo: match.price,
      alternativa: mejorAlt.name,
      precio_alternativa: mejorAlt.price,
      resultado: 'en_conversacion',
      mensaje: `La *${match.name}* cuesta ${match.price}€, pero con ${presupuestoCliente}€ te recomiendo la *${mejorAlt.name}* por ${mejorAlt.price}€. ¿Te interesa?`
    });
  } else {
    return JSON.stringify({
      compatible: false,
      modelo_solicitado: match.name,
      precio_modelo: match.price,
      precio_minimo: modelos[0].price,
      resultado: 'descartado_precio',
      mensaje: `Nuestro modelo más económico es la *${modelos[0].name}* por ${modelos[0].price}€. Con ${presupuestoCliente}€ no tenemos opciones disponibles. ¿Quieres reconsiderar tu presupuesto?`
    });
  }
}

